input.content:
'use server'

import { refresh } from 'next/cache'

const notificationPrefs = new Map<string, boolean>()

export async function getNotificationsEnabled(userId: string) {
  return notificationPrefs.get(userId) ?? false
}

export async function toggleNotifications(formData: FormData) {
  const userId = String(formData.get('userId'))
  notificationPrefs.set(userId, !(notificationPrefs.get(userId) ?? false))
  refresh()
}

import { getNotificationsEnabled, toggleNotifications } from './actions'

const USER_ID = 'user-1'

export default async function Home() {
  const enabled = await getNotificationsEnabled(USER_ID)

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <input type="hidden" name="userId" value={USER_ID} />
        <label>
          <input
            type="checkbox"
            checked={enabled}
            readOnly
          />
          Notifications are {enabled ? 'on' : 'off'}
        </label>
        <button type="submit">Toggle</button>
      </form>
    </main>
  )
}
